let pub={}, user=null, data={}, page='home', month=new Date(2026,9,1), selectedDate='', activeEvent='';
let selectedMember=sessionStorage.getItem('club_member')||'',switchingMember=false,reportDirty=false;
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function teamWordmark(name){if(/^(?:(?:MIKI|三木)\s*)?SHINING\s*CHEETAHS$/i.test(name.trim()))return '<strong class="team-wordmark miki-wordmark"><span class="team-name-white">MIKI </span><span class="team-name-yellow">S</span><span class="team-name-white">HINING C</span><span class="team-name-yellow">HEETAHS</span></strong>';return `<strong class="team-wordmark"><span class="team-name-white">${esc(name)}</span></strong>`;}
const brand=()=>{const name=pub.content?.name||'三木　SHINING CHEETAHS';return `<a class="brand" href="#home" aria-label="${esc(name)} トップページ"><img class="club-logo" src="/basketball-club/uploads/00000000000000000000000000000001.jpg" alt="三木 SHINING CHEETAHS ロゴ"><span>${teamWordmark(name)}<small>YOUTH BASKETBALL CLUB</small></span></a>`};
let renderEditToken='';
async function api(path,body){
 let payload=body?{...body}:null;
 if(payload&&user&&path!=='upload_stage'&&typeof stageUploadPayload==='function')payload=await stageUploadPayload(payload);
 if(payload&&user?.role!=='member'&&!['login','logout'].includes(path)&&!payload._edit_token)payload._edit_token=($('#modal')?.open?$('#modal').dataset.editToken:renderEditToken)||data.edit_token;
 const headers=selectedMember?{'X-Club-Member':selectedMember}:{};if(payload)headers['Content-Type']='application/json';
 const r=await fetch('/basketball-club/api/'+path,{method:payload?'POST':'GET',headers,...(payload?{body:JSON.stringify(payload)}:{})});const raw=await r.text();let v;try{v=JSON.parse(raw)}catch(e){throw Error('サーバーに接続できませんでした。少し待ってから、もう一度お試しください。')}
 if(r.status===409&&v.code==='edit_conflict'){
  const choice=await resolveEditConflict(v);
  if(choice==='mine'){
   const retry={...payload,_edit_token:v.token};
   if(path==='billing_plan') {const latest=await api('data');retry.revision=latest.billing_plan.revision;}
   return api(path,retry);
  }
  if(choice==='latest'){$('#modal').close();await refresh();throw Error('最新の保存内容を読み込みました。自分の変更は保存していません。');}
  throw Error('保存を中止しました。入力内容は残っています。');
 }
 if(r.status===401&&path!=='login'){user=null;data={};selectedMember='';sessionStorage.removeItem('club_member');document.querySelectorAll('dialog[open]').forEach(d=>d.close());page='login';location.hash='login';render();throw Error('ログインの有効期限が切れました。再ログインしてください。操作内容は保存されていません。');}
 if(!r.ok)throw Error(v.error||'読み込みに失敗しました。');return v;
}
function resolveEditConflict(info){return new Promise(resolve=>{
 const dialog=document.createElement('dialog');dialog.className='edit-conflict-dialog';
 const names={staff_activity:'スタッフ活動実績',staff_week_approval:'週ごとの承認',attendance_meta:'出欠予定の確認',event_details:'会場の地図',match_rosters:'参加メンバー',member_categories:'活動区分',member_families:'家族設定',survey_forms:'アンケート',survey_deadlines:'回答期限',shop_products:'商品',schedule_documents:'日程PDF',fee_adjustments:'会費の調整',trial_reviews:'体験申込の確認',events:'活動日程',reports:'実際の出欠',users:'会員・スタッフ',portal_items:'掲載内容',portal_entries:'報告の確認',results:'試合結果',game_stats:'スコア',event_briefings:'参加メンバー・詳細',meta:'会費設定'};
 dialog.innerHTML=`<h2>同じ項目が更新されています</h2><p>他のコーチ・管理者の操作などで、編集開始後に保存内容が変わりました。内容を比較して、どちらを優先するか選んでください。</p>${info.changes.map(c=>`<h3>${esc(names[c.item]||c.item)}</h3><details><summary>編集を始めた時の内容</summary><pre>${esc(conflictText(c.before))}</pre></details><h4>最新の保存内容</h4><pre>${esc(conflictText(c.latest))}</pre>`).join('')}<h3>自分が保存しようとしている内容</h3><pre>${esc(conflictText(info.proposed))}</pre><p>「自分の変更を優先して保存」は、この項目を自分の入力内容で上書きします。</p><div class="dialog-actions"><button class="outline" data-choice="cancel">編集に戻る</button><button class="outline" data-choice="latest">最新の内容を使う</button><button class="lime" data-choice="mine">自分の変更を優先して保存</button></div>`;
 const finish=choice=>{dialog.close();dialog.remove();resolve(choice)};dialog.addEventListener('cancel',e=>{e.preventDefault();finish('cancel')});dialog.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>finish(b.dataset.choice));document.body.append(dialog);dialog.showModal();
});}

function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
const dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString('ja-JP',{month:'long',day:'numeric',weekday:'short'});
function headerSocialIcon(kind,url){const instagram=kind==='Instagram',facebook=kind==='Facebook',icon=facebook?'<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M14 22v-9h3l.5-4H14V7c0-1.2.3-2 2-2h2V1.4A24 24 0 0 0 15 1c-3 0-5 1.8-5 5v3H7v4h3v9z"/></svg>':instagram?'<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="5" fill="none" stroke="currentColor" stroke-width="2"/><circle cx="12" cy="12" r="4" fill="none" stroke="currentColor" stroke-width="2"/><circle cx="17.5" cy="6.5" r="1.2" fill="currentColor"/></svg>':'<svg viewBox="0 0 32 32" aria-hidden="true"><path fill="currentColor" d="M27 14c0-6-5-10-12-10S3 8 3 14c0 5 4 9 10 10l-1 5 7-5c5-2 8-5 8-10Z"/><text x="15" y="17" text-anchor="middle" font-family="Arial,sans-serif" font-size="8" font-weight="bold" fill="#06c755">LINE</text></svg>';const cls='header-social-icon '+(facebook?'facebook-icon':instagram?'instagram-icon':'line-icon');return url?`<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer" aria-label="${kind}（別タブで開く）">${icon}</a>`:`<button type="button" class="${cls}" aria-label="${kind}（URL準備中）" title="${kind}（URL準備中）" disabled>${icon}</button>`;}
function header(){const links='<a href="#philosophy">チームについて</a><a href="#trial">体験会・入会案内</a><a href="#location">活動場所</a><a href="#staff-introduction">スタッフ紹介</a><a href="#other-activities">その他の活動</a><a href="#faq">FAQ</a>',socials=`<span class="header-social">${headerSocialIcon('Instagram',pub.content.instagram)}${headerSocialIcon('Facebook',pub.content.facebook)}${headerSocialIcon('公式LINE',pub.content.line)}</span>`;return `<header class="header"><div class="wrap nav">${brand()}<nav class="navlinks" aria-label="メインメニュー">${links}${socials}<a class="btn lime small" href="#login">ログイン</a></nav><div class="public-mobile-actions"><button type="button" class="public-menu-trigger" aria-haspopup="dialog" onclick="openPublicMenu()"><span aria-hidden="true">☰</span> メニュー</button><a class="btn lime small" href="#login">ログイン</a></div></div></header>`}
function trialGroups(e){const g=e.group_name||'';return {elementary:/小学生|小中学生|U9|U12/i.test(g),junior:/中学生|U15/i.test(g)}}
function calendar(events){let y=month.getFullYear(),m=month.getMonth(),start=new Date(y,m,1).getDay(),n=new Date(y,m+1,0).getDate();return `<div class="card calendar-card"><div class="calendar-head"><strong>${y}. ${String(m+1).padStart(2,'0')}</strong><div><button onclick="changeMonth(-1)" aria-label="前の月">‹</button><button onclick="changeMonth(1)" aria-label="次の月">›</button></div></div><div class="calendar">${['日','月','火','水','木','金','土'].map(d=>`<div class="dow">${d}</div>`).join('')}${'<span></span>'.repeat(start)}${Array.from({length:n},(_,i)=>{const d=`${y}-${String(m+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`,es=events.filter(e=>e.date===d),elementary=es.some(e=>trialGroups(e).elementary),junior=es.some(e=>trialGroups(e).junior);return `<button class="day ${es.length?'event':''} ${selectedDate===d?'selected':''}" onclick="selectDay('${d}')" aria-label="${d}${elementary?' 小学生体験会':''}${junior?' 中学生体験会':''}" aria-pressed="${selectedDate===d}"><span>${i+1}</span><span class="day-dots" aria-hidden="true">${elementary?'<i class="trial-dot elementary"></i>':''}${junior?'<i class="trial-dot junior"></i>':''}</span></button>`}).join('')}</div><div class="calendar-legend"><span><i class="trial-dot elementary" aria-hidden="true"></i>小学生</span><span><i class="trial-dot junior" aria-hidden="true"></i>中学生</span></div><p class="hint calendar-help">日付を選ぶと、その日の体験会を表示します。</p></div>`}
function trialListings(events){return ['elementary','junior'].map(group=>{const es=events.filter(e=>trialGroups(e)[group]);return `<section class="trial-age-group" aria-label="${group==='elementary'?'小学生':'中学生'}の体験会"><div class="trial-age-heading"><h3><i class="trial-dot ${group}" aria-hidden="true"></i>${group==='elementary'?'小学生':'中学生'}の体験会</h3><span>${group==='elementary'?'U9・U12':'U15'}</span></div>${es.map(e=>eventCard(e,true)).join('')||'<p class="empty">選択した期間の体験会はありません。</p>'}</section>`}).join('')}
function faqSection(){return `<section class="section wrap faq-section" id="faq"><div class="section-title"><div><div class="eng">FAQ</div><h2>体験・入会についてのよくある質問</h2></div></div>${(pub.faq||[]).map(q=>`<details><summary>${esc(q.q)}</summary><p>${esc(q.a)}</p></details>`).join('')}</section>`}
function eventCard(e,trial=false,wholeCard=false){if(trial)return trialDetailCard(e);const d=new Date(e.date+'T12:00:00');return `${wholeCard?`<a class="event-card upcoming-event-link" href="#schedule?event=${encodeURIComponent(e.id)}">`:'<article class="event-card">'}<${wholeCard?'div':'a'} class="date-block" ${wholeCard?'':`href="${trial?'#trial-list':'#schedule?event='+encodeURIComponent(e.id)}"`} aria-label="${esc(e.date+' '+e.title+'の詳細を見る')}"><small>${d.getMonth()+1}月</small><strong>${d.getDate()}</strong><small>${['SUN','MON','TUE','WED','THU','FRI','SAT'][d.getDay()]}</small></${wholeCard?'div':'a'}><div><span class="tag">${esc(e.group_name)}</span><h3>${esc(e.title)}</h3><p>${esc(e.time)}<br>${esc(e.place)}</p></div>${trial?`<button class="outline small" onclick="trialForm('${e.id}')">参加する</button>`:''}</${wholeCard?'a':'article'}>`}
function publicPage(){let c=Object.fromEntries(Object.entries(pub.content).map(([k,v])=>[k,typeof v==='string'?v.replace(/年長[〜～]/g,'小学1年生〜').replace(/年長[・、]?/g,''):v]));const events=pub.events.filter(e=>e.date.startsWith(`${month.getFullYear()}-${String(month.getMonth()+1).padStart(2,'0')}`)&&(!selectedDate||e.date===selectedDate));$('#app').innerHTML=`${header()}<main><section class="hero"><div class="hero-media">${c.hero?`<img class="hero-photo" src="${esc(c.hero)}" alt="${esc(c.name)}のバスケットボール活動風景" width="640" height="640" fetchpriority="high" decoding="async">`:''}</div><div class="wrap"><div class="eyebrow">PLAY TOGETHER. GROW TOGETHER.</div><h1>${esc(c.headline)}</h1><p class="club-area">${esc(c.region||'兵庫県三木市')}の小学生・中学生バスケットボールクラブ</p><p>${esc(c.intro)}</p><div class="hero-bottom"><div class="hero-contact-actions"><div class="hero-trial-row"><a class="btn lime" href="#trial-list">体験会に参加する</a><div class="hero-small">小学生・中学生 ／ 初心者も大歓迎</div></div></div></div></div><div class="hero-num">CHEETAHS</div></section><div class="wrap"><div class="notice"><b>NEWS</b><time>2026.09</time><span>${esc(c.notice)}</span></div></div><section class="section wrap" id="philosophy"><div class="about-grid"><div><div class="eyebrow">OUR PHILOSOPHY</div><h2>バスケを通して、<br>「生きる力」を育てる。</h2></div><div><p>${esc(c.philosophy)}</p><div class="values"><div><span>01</span>挑戦する心</div><div><span>02</span>仲間への敬意</div><div><span>03</span>考える力</div></div></div></div></section><section class="section schedule-section" id="trial"><div class="wrap"><div class="section-title"><div><div class="eng">TRYOUT SCHEDULE</div><h2>その一歩が、夢中のはじまり。</h2></div><p class="tryout-intro">${esc(c.recruit)}</p></div><div class="schedule-grid"><div>${calendar(pub.events)}</div><div id="trial-list">${trialListings(events)}${selectedDate?'<button class="text-link" onclick="selectDay(\'\')">今月のすべての体験会を見る</button>':''}<p class="hint">持ち物：${esc(c.equipment)}</p></div></div></div></section>${trialReviewsSection()}<section class="section wrap" id="location"><div class="section-title"><div><div class="eng">OUR HOME COURT</div><h2>練習場所・練習風景</h2></div></div><div class="location-grid"><div>${c.gallery||c.hero?`<img src="${esc(c.gallery||c.hero)}" alt="SHINING CHEETAHSの活動風景" width="640" height="640" loading="lazy" decoding="async">`:'<div class="card empty">練習写真は管理画面から設定できます。</div>'}</div><div><h3>${esc(c.place)}</h3><p class="muted">${esc(c.address)}</p><div class="info-row"><b>練習日</b><span>${esc(c.practice)}</span></div><div class="info-row"><b>持ち物</b><span>${esc(c.equipment)}</span></div><div class="social">${social(c.instagram,'Instagram')}${social(c.facebook,'Facebook')}${social(c.line,'公式 LINE')}</div></div></div></section>${publicStaffSection()}${mikitivSection()}${faqSection()}</main><footer class="footer"><div class="wrap">${brand()}<p>${esc(c.subname)}<br>© 2026 ${esc(c.name)} BASKETBALL CLUB</p></div></footer><div class="demo-strip">操作体験用デモ ｜ 日程・人物・活動場所はサンプルです</div>`}
function social(url,label){const theme=label==='Instagram'?'social-instagram':label==='Facebook'?'social-facebook':'social-line';return url?`<a class="btn small ${theme}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label}</a>`:`<button class="small ${theme}" onclick="toast('公式URLは管理画面から設定できます。')">${label}（準備中）</button>`}
function changeMonth(n){month=new Date(month.getFullYear(),month.getMonth()+n,1);selectedDate='';publicPage()}
function selectDay(d){selectedDate=d;publicPage()}
async function refresh(){pub=await api('public');user=(await api('me')).user;if(!user&&selectedMember){selectedMember='';sessionStorage.removeItem('club_member');user=(await api('me')).user;}if(user)data=await api('data');document.documentElement.style.setProperty('--lime',pub.content.accent);document.title=pub.content.seo_title||pub.content.name+' | バスケットボールクラブ';render()}
function render(){page=(location.hash.slice(1)||'home').split('?')[0];if(page==='schedule'){const eid=new URLSearchParams(location.hash.split('?')[1]||'').get('event'),e=data.events?.find(e=>e.id===eid);if(e){attendanceMonth=new Date(e.date+'T12:00:00');coachScheduleDay=e.date;categoryFilter='';setTimeout(()=>document.getElementById('plan-'+e.id)?.scrollIntoView({block:'start'}),0);}}if(page==='trial-review'){trialReviewPage();return}if(page==='finance-register'){financeRegistrationPage();return}if(page==='register'){registrationPage();return}if(page==='coach-register'){coachRegistrationPage();return}if(page==='forgot-password'){forgotPasswordPage();return}if(page==='password-reset'){passwordResetPage();return}if(page==='account-setup'){accountSetupPage();return}if(['philosophy','trial','trial-list','location','faq','staff-introduction','other-activities'].includes(page)){publicPage();setTimeout(()=>document.getElementById(page)?.scrollIntoView(),0);return}if(page==='all-staff'){staffIntroductionPage();return;}if(page==='home')publicPage();else if(page==='login'||!user)loginPage();else dashboard()}
function loginPage(){$('#app').innerHTML=`${header()}<div class="login-layout"><div class="login-brand"><div class="eyebrow">CHEETAHS CLUB PORTAL</div><div class="eng">ONE TEAM.<br>ONE DREAM.</div><h1>コートの外でも、<br>チームはひとつ。</h1><p>練習の予定、今日のコンディション。<br>次の一歩を、ここから。</p></div><div class="login-main"><span class="eyebrow">MEMBER & STAFF</span><h2>ログイン</h2><p class="hint">登録済みのID・パスワードを入力してください。</p><form onsubmit="login(event)"><label class="field">ログインID<input id="login-id" name="id" autocomplete="username" required placeholder="例：member01"></label><label class="field">パスワード<input id="login-pw" type="password" name="password" autocomplete="current-password" required></label><label class="check-row hint"><input type="checkbox" onchange="$('#login-pw').type=this.checked?'text':'password'">パスワードを表示</label><p id="login-error" class="error" role="alert"></p><button class="lime" style="width:100%" type="submit">ログイン</button></form><div class="account-login-links"><div class="registration-button-row"><a class="btn outline" href="#register">会員新規登録</a><a class="btn outline" href="#finance-register">役員新規登録</a><a class="btn outline" href="#coach-register">コーチ新規登録</a></div><a class="text-link" href="#forgot-password">パスワードをお忘れの方</a></div><div class="demo-accounts"><b>デモを試す</b><p>下のボタンで体験用のID・パスワードを入力できます。</p><button onclick="fillLogin('member01','Cheetahs123!')">会員</button><button onclick="fillLogin('coach01','Coach123!')">コーチ</button><button onclick="fillLogin('admin01','Admin123!')">管理者</button><button onclick="fillLogin('officer01','Officer123!')">役員</button><div class="hint">デモには実在するお子さまの情報を入力しないでください。</div></div></div></div>`}
function fillLogin(id,pw){$('#login-id').value=id;$('#login-pw').value=pw}
async function login(ev){ev.preventDefault();const b=ev.submitter;b.disabled=true;try{selectedMember='';sessionStorage.removeItem('club_member');const loginResult=await api('login',Object.fromEntries(new FormData(ev.target)));location.hash=['condition','schedule','attendance-list','admin-guide'].includes(page)?page:'dashboard';await refresh();window.scrollTo({top:0,behavior:'instant'})}catch(e){if($('#login-error'))$('#login-error').textContent=e.message;else toast(e.message)}finally{b.disabled=false}}
async function logout(){selectedMember='';sessionStorage.removeItem('club_member');await api('logout',{});user=null;data={};location.hash='login'}
const unreadTrials=()=> (data.trials||[]).filter(t=>!t.reviewed_at);
function trialNotice(){const n=unreadTrials().length;return n?`<aside class="trial-notice" role="status"><div><b>未確認の体験申込が ${n} 件あります</b><p>お名前・希望日程・連絡先をご確認ください。</p></div><a class="btn small" href="#trials">申込を確認</a></aside>`:''}
