function eventList(events,staff){return events.map(e=>`<div class="card" style="margin-bottom:16px"><div class="page-heading" style="margin-bottom:12px"><div><span class="tag ${e.kind==='試合'?'warn':''}">${esc(e.kind)}</span><h2 style="margin:9px 0">${esc(e.title)}</h2><p>${dateLabel(e.date)}　${esc(e.time)} ／ ${esc(e.group_name)}</p></div>${staff?`<button class="outline small" onclick="eventForm('${e.id}')">編集</button>`:`<button class="lime small" onclick="activeEvent='${e.id}';location.hash='condition';render();document.getElementById('member-report')?.scrollIntoView()">出欠を報告</button>`}</div><p style="margin:0;font-size:14px">会場：${esc(e.place)}<br>${esc(e.note)}</p></div>`).join('')||'<div class="card empty">日程はありません。</div>'}
function filterEvents(kind){$('#event-list').innerHTML=eventList(data.events.filter(e=>!kind||e.kind===kind),user.role!=='member')}
function reportHistory(rs){const reports=rs.filter(hasCondition).slice().sort((a,b)=>{const date=r=>data.events.find(e=>e.id===r.event_id)?.date||r.updated||'';return date(b).localeCompare(date(a))||(b.updated||'').localeCompare(a.updated||'');});const card=r=>`<article class="card"><b>${esc(data.events.find(e=>e.id===r.event_id)?.date||'')} ${esc(data.events.find(e=>e.id===r.event_id)?.title||'')}</b><p>体の調子：${conditionValue(r,'body_condition')}<br>心の調子：${conditionValue(r,'mind_condition')}<br>朝ご飯：${conditionValue(r,'breakfast')}</p><p class="service-text">調子の悪いところ：${esc(r.unwell_area||'—')}<br>その他の連絡事項：${esc(r.note||'—')}</p></article>`;return reports.length?`<div class="stack condition-history">${reports.slice(0,3).map(card).join('')}</div>${reports.length>3?`<details class="condition-history-more"><summary><span class="when-closed">もっと見る（残り${reports.length-3}件）</span><span class="when-open">閉じる（最新3件）</span></summary><div class="stack">${reports.slice(3).map(card).join('')}</div></details>`:''}`:'<div class="empty">まだ報告はありません。</div>'}

