async function submitReport(ev){ev.preventDefault();await submit(ev,'report',Object.fromEntries(new FormData(ev.target)),'コーチに体調・出欠を送信しました。')}
async function saveActual(uid,value){try{const r=await api('actual',{user_id:uid,event_id:activeEvent,actual:value});await refresh();toast(r.excel.ok?'出欠を記録し、Excelを更新しました。':r.excel.message)}catch(e){toast(e.message);await refresh()}}
function memberTable(us,admin){return `<table class="member-directory-table"><thead><tr><th>氏名 / ID</th><th>${page==='staff-members'?'担当学年':'学年'}</th>${page==='staff-members'?'<th>スタッフ区分</th>':'<th>学校名</th><th>カテゴリー区分</th>'}<th>権限</th><th>在籍状況</th>${page==='staff-members'?'':'<th>実際の出欠</th>'}${admin&&page!=='staff-members'?'<th>ログイン承認</th><th>承認操作</th>':''}${admin?'<th>管理</th>':''}</tr></thead><tbody>${us.map(m=>`<tr><td>${page!=='staff-members'?guardianCallButton(m):''}<b>${esc(m.name)}</b><br><span class="hint">${esc(m.id)}</span></td><td>${page==='staff-members'?staffAssignmentTags(m.grade):esc(m.grade)}</td>${page==='staff-members'?`<td>${esc(m.staff_kind||'コーチ')}</td>`:`<td>${esc(m.school||'未登録')}</td><td>${staffAssignmentTags(m.categories)}</td>`}<td>${({member:'会員',coach:'コーチ',admin:'管理者'})[m.role]}</td><td><span class="tag ${m.active?'':'gray'}">${esc(enrollmentStatusText(m.enrollment)||(m.active?'在籍':'退会'))}</span></td>${page==='staff-members'?'':`<td>${m.role==='member'?`<button class="outline small" onclick="memberActualHistory('${m.id}')">出欠履歴を見る</button>`:'—'}</td>`}${admin&&page!=='staff-members'?`<td>${memberRegistrationStatus(m)}</td><td>${memberRegistrationControls(m)}</td>`:''}${admin?`<td><div class="member-management-actions"><button class="outline small" onclick="userForm('${m.id}')">編集</button>${adminFull()?`<button class="outline small" data-id="${esc(m.id)}" onclick="resetCredentialForm(this.dataset.id)">ID・PWをリセット</button>`:''}${page==='staff-members'?`<button class="outline small" data-id="${esc(m.id)}" onclick="staffIntroForMember(this.dataset.id)">紹介を編集</button>${adminFull()?`<button class="lime small" type="button" data-id="${esc(m.id)}" onclick="approvalPerson=this.dataset.id;location.hash='staff-approval-settings'">活動承認ページへ</button>${m.id!==user.id&&m.id!=='admin01'?`<button class="outline small" type="button" data-id="${esc(m.id)}" onclick="removeStaff(this.dataset.id)">削除</button>`:''}`:''}`:''}${m.role==='member'?`<button class="outline small" onclick="removeMember('${m.id}')">削除</button>`:''}</div></td>`:''}</tr>`).join('')}</tbody></table>`}
function filterMembers(q){const staffPage=page==='staff-members';$('#member-table').innerHTML=memberTable(data.users.filter(u=>(staffPage?['coach','admin'].includes(u.role):u.role==='member')&&(u.name+u.id).toLowerCase().includes(q.toLowerCase())),user.role==='admin')}
function memberDirectoryPage(admin){const staffPage=page==='staff-members',people=data.users.filter(u=>staffPage?['coach','admin'].includes(u.role):u.role==='member'),status=data.member_input_status;return (staffPage&&adminFull()?coachRegistrationPanel():'')+heading(staffPage?'コーチ・スタッフ一覧':'会員一覧',staffPage?'コーチ・スタッフの所属・権限・在籍状況を管理します。':'学年は毎年4月1日に自動更新します。休会中もログインできます。退会するとログインできなくなります。',admin?'<button class="lime" onclick="userForm()">＋ '+(staffPage?'スタッフ':'会員')+'を追加</button>':'')+`${adminFull()&&staffPage?adminAccessPanel():''}${admin&&!staffPage?registrationApprovals():''}${admin?`<details class="card"><summary>ローカルExcelからの反映</summary><p>固定PCの「data / 会員スタッフ入力.xlsx」の「${staffPage?'スタッフ入力':'会員入力'}」シートを編集して保存してください。デモサーバー起動中は約5秒ごとに確認します。</p><p>住所・電話番号・保護者氏名など「ローカルのみ」の列はサイトへ取り込みません。ログイン・日程表示に必要な氏名、ID、所属などを反映します。</p><p>行を削除してもアカウントは削除されません。「在籍状況」を「退会」または「停止」にするとログインを停止します。初期パスワードは新規IDのみ使用し、登録後はExcelの該当欄を空にできます。</p><p class="hint">${esc(status?.message||'入力Excelは未反映です。')} ${esc(status?.updated||'')}</p><p class="hint">本番WordPressと固定PC間の同期は、本番導入時に接続します。現在はこのデモを動かしているPCのExcelを読み込みます。</p></details>`:''}<div class="card"><div class="toolbar"><input class="filter" placeholder="名前・IDで検索" aria-label="会員検索" oninput="filterMembers(this.value)">${admin?(!staffPage?'<button type="button" class="lime" onclick="downloadMemberAttendance()">全会員の出欠履歴CSV</button>':'<button type="button" class="lime" onclick="downloadStaffDirectory()">コーチ・スタッフ一覧CSV</button>'):''}</div><div class="member-scroll-controls"><span>↔ 左右にスクロールできます</span><input type="range" min="0" max="100" value="0" aria-label="会員一覧の横スクロール" oninput="scrollMemberTable(this.value)"></div><div class="table-wrap" id="member-table" onscroll="syncMemberScroll(this)">${memberTable(people,admin)}</div></div>`;}

function selectField(label,name,values,current){return `<label class="field">${label}<select name="${name}">${values.map(v=>{const pair=Array.isArray(v)?v:[v,v];return `<option value="${esc(pair[0])}" ${String(current)===String(pair[0])?'selected':''}>${esc(pair[1])}</option>`}).join('')}</select></label>`}
function userForm(id){const m=data.users.find(u=>u.id===id)||{role:page==='staff-members'?'coach':'member',active:1};modal((page==='staff-members'?'スタッフ':'会員')+(id?'を編集':'を追加'),`<form onsubmit="saveUser(event,'${id||''}')"><div class="form-grid">${!id&&m.role==='member'?`<input type="hidden" name="id" value="player_${crypto.randomUUID().replaceAll('-','').slice(0,16)}"><p class="hint">選手を登録後、専用の登録コードを保護者へ案内してください。ログインID・パスワードは保護者が設定します。</p>`:field('会員ID（変更不可）','id',m.id||'')}${field('氏名','name',m.name||'')}${m.role==='member'?`<div class="full">${field('学校名','school',m.school||'','text',false)}</div>`:''}<div data-member-grade ${m.role!=='member'?'hidden':''}>${selectField('学年','grade',accountGrades,m.role==='member'?(m.grade||'年長'):'年長')}</div><fieldset class="staff-assignment-options" data-staff-assignment ${m.role==='member'?'hidden':''}><legend>担当学年・カテゴリー（複数選択可）</legend>${staffAssignmentGroups.map(group=>`<label class="check-row"><input type="checkbox" name="staff_assignments" value="${group}" ${splitStaffAssignments(m.grade).includes(group)?'checked':''}>${coachCategoryLabel(group)}</label>`).join('')}</fieldset><div data-member-only ${m.role!=='member'?'hidden':''}>${selectField('カテゴリー区分','categories',memberCategoryOptions(m.categories),m.categories||'男子A')+'<p class="hint">（会費用カテゴリーとは別）</p>'}</div>${selectField('権限','role',[['member','会員'],['coach','コーチ'],['admin','管理者']],m.role).replace('<select ','<select onchange="toggleStaffAssignment(this.value);staffRoleChanged(this)" ')}${m.role==='member'?enrollmentStatusField('enrollment_status',m.enrollment||{status:m.active?'在籍':'退会'}):selectField('在籍状況','active',[[1,'在籍'],[0,'退会']],m.active)}<div class="full" data-member-only ${m.role!=='member'?'hidden':''}>${field('兄弟の紐づけ用グループID（任意）','family_id',m.family_id||'','text',false)}</div></div>${m.role!=='member'?field(id?'新しいパスワード（変更時のみ）':'初期パスワード（任意・登録コードで本人が設定）','password','','password',false):''}<p class="hint">同じ家族IDを設定した会員は、1回のログインで相互に切り替えられます。別家庭には異なるIDを設定してください。スタッフには適用しません。退会者は切り替え対象から外れます。</p>${id&&m.role==='member'?`<section class="member-form-guardians"><h3>保護者情報</h3>${memberGuardianList(m)}</section>`:''}${id&&m.role==='member'?memberInvitePanel(id):''}<div class="error" role="alert"></div><div class="dialog-actions"><button class="lime">保存する</button></div></form>`);if(id)$('#modal [name=id]').readOnly=true;if(page==='staff-members')initStaffPermissions(m);}
async function saveUser(ev,id){ev.preventDefault();const formData=new FormData(ev.target),d=Object.fromEntries(formData);if(d.role!=='member')d.grade=formData.getAll('staff_assignments').join('、');delete d.staff_assignments;if(page==='staff-members'&&d.id!=='admin01'&&d.id!==user.id){d.staff_permissions=d.role==='admin'?(ev.target.staffPermissions||{}):{};d.staff_permission_revision=ev.target.staffPermissionRevision||0;d.role='coach';}if(d.enrollment_status)d.active=d.enrollment_status==='即日退会'?'0':'1';if(d.active==='0'){const ok=await confirmAction('退会・ログイン停止にしますか？','この会員のログインを停止します。過去の記録は残ります。');if(!ok)return;}await submit(ev,'user',d,'会員情報を保存しました。')}
async function confirmAction(title,message){return window.confirm(title+'\n'+message)}
function eventForm(id,duplicate=false){const sourceId=id;const e=data.events.find(e=>e.id===id)||{date:new Date().toLocaleDateString('sv-SE'),kind:'練習'};if(duplicate)id='';modal(duplicate?'日程を複製（日付を確認してください）':id?'日程を編集':'日程を追加',`${id&&e.kind==='練習'?`<p><button type="button" class="lime" onclick="openWeeklyRepeat('${id}')">毎週繰り返し登録</button></p>`:''}<form ${id?'data-existing-event="true"':''} onsubmit="saveEvent(event,'${id||''}')">${scheduleTitleField(e.title||'',e.kind)}<div class="form-grid">${field('日付','date',e.date,'date')}${field('時間','time',e.time||'09:00〜11:00')}${eventCategoryField(e.group_name||'男子A')}</div>${venueFields(e.place||'',e.address||'')}${field('地図URL（Googleマップなど・任意）','map_url',e.map_url||'','url',false)}<label class="field">詳細・集合時間<textarea name="note">${esc(e.note||'')}</textarea></label><div class="error" role="alert"></div><div class="dialog-actions">${id?`<button type="button" class="outline danger" onclick="deleteRecord('event','${id}')">日程を削除</button>`:''}<button class="lime">保存する</button></div></form>`)}
async function saveEvent(ev,id){ev.preventDefault();await submit(ev,'event',{...Object.fromEntries(new FormData(ev.target)),id},'日程を保存しました。')}
function resultForm(id){if(user?.role!=='admin'){toast('管理者のみ編集できます。');return;}const r=data.results.find(r=>r.id===id)||{date:new Date().toLocaleDateString('sv-SE'),group_name:page==='results'?resultsCategory:teamHistoryCategory};modal(id?'試合結果を編集':'試合結果を追加',`<form onsubmit="saveResult(event,'${id||''}')"><div class="form-grid">${field('日付','date',r.date,'date')}${selectField('対象チーム','group_name',[['','選択してください'],...[...new Set(['男子A','男子B','女子U９','女子U12','U15アドバンス','U15ベーシック',...(r.group_name?[r.group_name]:[])])].map(x=>[x,x])],r.group_name||'').replace('<select ','<select required ')}${field('対戦相手','opponent',r.opponent||'')}${field('自チームの得点','ours',r.ours??0,'number')}${field('相手の得点','theirs',r.theirs??0,'number')}</div><label class="field">試合の振り返り<textarea name="note">${esc(r.note||'')}</textarea></label>${field('YouTube限定公開URL','video',r.video||'','url',false)}<p class="hint">YouTubeで限定公開に設定した動画のURLを入力してください。URLを知っている人はYouTube上で視聴できます。</p><div class="error" role="alert"></div><div class="dialog-actions">${id?`<button type="button" class="outline danger" onclick="deleteRecord('result','${id}')">結果を削除</button>`:''}<button class="lime">保存する</button></div></form>`)}
async function saveResult(ev,id){ev.preventDefault();await submit(ev,'result',{...Object.fromEntries(new FormData(ev.target)),id},'試合結果を保存しました。')}
async function deleteRecord(type,id){if(!await confirmAction('削除しますか？',type==='event'?'この日程の出欠・体調報告・体験申込も削除されます。':'試合結果を削除します。'))return;try{await api(type,{id,delete:true});$('#modal').close();await refresh();toast('削除しました。')}catch(e){toast(e.message)}}
function youtubeEmbed(url){try{const u=new URL(url);let id=u.hostname==='youtu.be'?u.pathname.slice(1):u.searchParams.get('v')||u.pathname.split('/').pop();return /^[\w-]{11}$/.test(id)?'https://www.youtube-nocookie.com/embed/'+id:''}catch{return ''}}
function settings(){const c=pub.content;const labels={region:'活動地域',seo_title:'検索結果のページタイトル',seo_description:'検索結果の説明文',name:'チーム名',subname:'日本語表記',headline:'トップの見出し',intro:'トップの紹介文',philosophy:'チーム理念',recruit:'募集案内',notice:'お知らせ',place:'練習場所',address:'住所・アクセス',equipment:'持ち物',instagram:'Instagram URL',facebook:'FacebookページのURL（未登録は空欄）',line:'公式LINEの友だち追加URL（未登録は空欄）',hero:'トップ写真のURL',gallery:'練習写真のURL',accent:'アクセントカラー'};return heading('サイト編集','公開ページの内容を編集して保存すると、すぐに反映されます。','<div class="site-edit-actions"><a class="btn outline" href="/#home" target="_blank" rel="noopener noreferrer">公開ページを見る</a><button type="button" class="outline" onclick="backFromSiteEditor()">一つ前の画面に戻る</button></div>')+`<div class="card"><form onsubmit="saveSettings(event)"><div class="form-grid">${Object.entries(labels).map(([k,label])=>['headline','intro','philosophy','recruit','seo_description'].includes(k)?`<label class="field full">${label}<textarea name="${k}">${esc(c[k])}</textarea></label>`:field(label,k,c[k],k==='accent'?'color':'text',false)).join('')}</div>${practiceScheduleEditor(c)}<p class="hint">写真は https:// の画像URLで指定します。Instagram投稿ページのURLでは画像を直接表示できません。公式写真が未設定の場合は、練習写真の案内を表示します。</p><div class="error" role="alert"></div><button class="lime">変更を保存する</button></form></div>`}
async function saveSettings(ev){ev.preventDefault();const payload=Object.fromEntries(new FormData(ev.target));if(ev.target.querySelector('.practice-schedule-editor'))payload.practice_slots=JSON.stringify([...ev.target.querySelectorAll('.practice-slot-row')].map(row=>({group:row.dataset.group,day:row.querySelector('[data-slot=day]').value,start:row.querySelector('[data-slot=start]').value,end:row.querySelector('[data-slot=end]').value})));await submit(ev,'content',payload,'公開ページを更新しました。')}
async function syncExcel(b){b.disabled=true;try{const r=await api('sync',{});await refresh();toast(r.excel.ok?'Excelを更新しました。':r.excel.message)}catch(e){toast(e.message)}finally{b.disabled=false}}
const originalSettings=settings;
settings=function(){return originalSettings().replace('<div class="form-grid">',`<div class="form-grid"><label class="field">トップ写真をアップロード<input type="file" accept="image/jpeg,image/png,image/webp" onchange="uploadPhoto(this,'hero')"></label><label class="field">練習写真をアップロード<input type="file" accept="image/jpeg,image/png,image/webp" onchange="uploadPhoto(this,'gallery')"></label>`).replace('写真は https:// の画像URLで指定します。','写真はアップロード、または https:// の画像URLで指定します。')+`<section class="card"><h2>コーチ・スタッフ紹介の編集</h2><p>写真・自己紹介・担当クラス・審判資格は、コーチ・スタッフ一覧から編集できます。</p><a class="btn outline" href="#staff-members">コーチ・スタッフを編集</a></section>`+otherActivitiesEditor()+trialReviewsEditor()};
async function uploadPhoto(input,target){const f=input.files[0];if(!f)return;if(f.size>5*1024*1024){toast('5MB以下の画像を選択してください。');return}input.disabled=true;try{const encoded=await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(f)});const result=await api('upload',{image:encoded});document.querySelector(`[name="${target}"]`).value=result.url;toast('画像を読み込みました。「変更を保存する」で反映します。')}catch(e){toast(e.message)}finally{input.disabled=false}}
let polling=false;
setInterval(async()=>{if(document.querySelector('.edit-conflict-dialog')||switchingMember||polling||document.querySelector('.quick-actual button:disabled,.basket-note-status select[data-saving]')||document.hidden||document.querySelector('dialog[open]')||(page!=='attendance-list'&&document.activeElement?.matches('input,textarea,select'))||['settings','schedule','surveys','account-setup','register','forgot-password','password-reset','billing-settings','billing-individual','portal-admin','staff-approvals','finance-admin','accounting'].includes(page)||(page==='condition'&&user?.role==='member'))return;polling=true;try{if(user){const context=selectedMember;const fresh=await api('data');if(context!==selectedMember)return;if(JSON.stringify(fresh)!==JSON.stringify(data)){const oldIds=new Set((data.trials||[]).map(t=>t.id));const added=(fresh.trials||[]).filter(t=>!oldIds.has(t.id));data=fresh;if(user.role!=='member'&&added.length)toast(`新しい体験申込が${added.length}件届きました。`);if(!['home','philosophy','trial','trial-list','location','login'].includes(page))dashboard()}}else if(['home','philosophy','trial','trial-list','location'].includes(page)){const fresh=await api('public');if(JSON.stringify(fresh)!==JSON.stringify(pub)){pub=fresh;document.documentElement.style.setProperty('--lime',pub.content.accent);publicPage()}}}catch(e){if(e.message==='ログインしてください。'){user=null;data={};location.hash='login';toast('再ログインしてください。')}}finally{polling=false}},15000);
document.addEventListener('change',ev=>{if(ev.target.matches('#modal [name=group_name],#modal [name=kind]')){const form=ev.target.closest('form');const time=form?.querySelector('[name=time]');if(time&&form.querySelector('[name=group_name]')?.value==='中学生'&&form.querySelector('[name=kind]')?.value==='体験会'&&!form.dataset.existingEvent)time.value='19:00〜';}});
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'open_club_schedule',title:'活動日程を開く',description:'ログイン中の会員・スタッフの活動日程を開きます。記録は変更しません。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:async input=>{if(!input||Object.keys(input).length)throw Error('入力は空のオブジェクトです。');if(!user)throw Error('ログインしてください。');location.hash='schedule';render();return {page:'schedule',events:data.events.length}}})}catch{}}
function modal(title,body){$('#modal').dataset.editToken=renderEditToken||data.edit_token||'';$('#modal').innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button onclick="$('#modal').close()" aria-label="閉じる">×</button></div>${body}<div class="modal-bottom-actions"><button type="button" class="outline" onclick="this.closest('dialog').close()">閉じる</button></div>`;$('#modal').showModal()}
function field(label,name,value='',type='text',required=true){const input=`<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}>`;return `<label class="field">${label}${type==='date'?`<span class="club-date-display">${input}<span class="club-date-text" aria-hidden="true">${esc(value?String(value).replaceAll('-','/'):'年 / 月 / 日')}</span><span class="club-date-icon" aria-hidden="true">▦</span></span>`:input}</label>`}
function trialForm(id){const e=pub.events.find(e=>e.id===id);modal('体験会に申し込む',`<p>${esc(e.title)}<br>${dateLabel(e.date)} ${esc(e.time)}</p><form onsubmit="submitTrial(event,'${id}')"><div class="form-grid">${field('お子さまのお名前','name')}${selectField('学年','grade',[['','選択してください'],'年長',...Array.from({length:6},(_,i)=>'小学'+(i+1)+'年'),...Array.from({length:3},(_,i)=>'中学'+(i+1)+'年')],'')}${field('保護者のお名前','parent_name')}${field('電話番号','phone','','tel')}</div><label class="field"><span>連絡先の種類 <small style="color:#687782;font-weight:normal">（メールアドレス または LINE IDを選択してください）</small></span><select name="contact_type" onchange="updateTrialContact(this)" required><option value="email">メールアドレス</option><option value="line">LINE ID</option></select></label><label class="field"><span id="trial-contact-label">メールアドレス</span><input name="contact" type="email" required maxlength="200" autocomplete="email"></label><label class="field">ご質問・連絡事項<textarea name="note"></textarea></label><div class="error" role="alert"></div><div class="dialog-actions"><button class="lime">申し込む</button></div></form>`)}
function updateTrialContact(select){const input=select.form.elements.contact,isEmail=select.value==='email';select.form.querySelector('#trial-contact-label').textContent=isEmail?'メールアドレス':'LINE ID';input.type=isEmail?'email':'text';input.autocomplete=isEmail?'email':'off';input.value='';input.placeholder=isEmail?'例：name@example.com':'例：cheetahs_parent';}

async function submitTrial(ev,id){ev.preventDefault();await submit(ev,'trial',{...Object.fromEntries(new FormData(ev.target)),event_id:id},'体験会の申し込みを受け付けました。')}
async function submit(ev,path,payload,message){const b=ev.submitter;b.disabled=true;try{const r=await api(path,payload);$('#modal').close();reportDirty=false;await refresh();toast(r.excel?.ok===false?r.excel.message:message)}catch(e){const err=ev.target.querySelector('.error');if(err)err.textContent=e.message;else toast(e.message)}finally{b.disabled=false}}
window.addEventListener('hashchange',()=>{render();if(['personal-history','team-history','scorecard','condition'].includes(page))window.scrollTo({top:0,behavior:'instant'});});refresh().catch(e=>{$('#app').innerHTML='<div class="wrap section"><h1>サイトを読み込めませんでした</h1><p>'+esc(e.message)+'</p><button onclick="location.reload()">再読み込み</button></div>'});

async function reviewTrial(id,button){button.disabled=true;try{const r=await api('trial_review',{id});await refresh();toast(r.excel?.ok?'確認済みにし、Excelにも反映しました。':r.excel?.message||'確認済みにしました。')}catch(e){toast(e.message)}finally{button.disabled=false}}

function memberAttendanceRows(id,month=''){
 return (data.reports||[]).filter(r=>(!id||r.user_id===id)&&r.actual).map(r=>({r,e:data.events.find(e=>e.id===r.event_id),m:(data.users||[]).find(m=>m.id===r.user_id)})).filter(x=>x.m?.role==='member'&&(!month||x.e?.date?.startsWith(month))).sort((a,b)=>(b.e?.date||'').localeCompare(a.e?.date||'')||(a.e?.time||'').localeCompare(b.e?.time||'')||a.r.user_id.localeCompare(b.r.user_id));
}
function memberActualHistory(id,month='',pageIndex=0){
 const m=data.users.find(u=>u.id===id);if(!m)return;
 const all=memberAttendanceRows(id),months=[...new Set(all.map(x=>x.e?.date?.slice(0,7)).filter(Boolean))].sort().reverse(),rows=memberAttendanceRows(id,month),pages=Math.max(1,Math.ceil(rows.length/10)),current=Math.min(Math.max(0,pageIndex),pages-1),visible=rows.slice(current*10,current*10+10);
 modal(m.name+'さんの実際の出欠',`<p>コーチが記録した実績です。事前の出欠予定とは分けて表示します。</p><div class="member-history-tools"><label class="field">表示する月<select onchange="memberActualHistory('${id}',this.value,0)"><option value="">全期間</option>${months.map(x=>`<option value="${x}" ${month===x?'selected':''}>${x.replace('-','年')}月</option>`).join('')}</select></label><button type="button" class="lime" onclick="downloadMemberAttendance('${id}','${month}')" ${rows.length?'':'disabled'}>この会員のCSVを出力</button></div><p class="hint">${rows.length}件${rows.length?` ／ ${current*10+1}〜${Math.min((current+1)*10,rows.length)}件を表示`:''}。CSVには${month?esc(month)+'の':'全期間の'}全件を出力します。</p><div class="stack">${visible.map(({r,e})=>`<article class="card"><b>${esc(e?.date||'')} ${esc(e?.title||'日程不明')}</b><p>${esc(e?.time||'')} ／ ${esc(e?.place||'')}<br>出欠予定：${esc(r.attendance||'未回答')}<br>実際の出欠：<strong>${esc(r.actual)}</strong></p></article>`).join('')||'<p>この期間の実際の出欠はまだ記録されていません。</p>'}</div>${pages>1?`<div class="member-history-paging"><button type="button" class="outline" ${current===0?'disabled':''} onclick="memberActualHistory('${id}','${month}',${current-1})">前の10件</button><span>${current+1} / ${pages}</span><button type="button" class="outline" ${current===pages-1?'disabled':''} onclick="memberActualHistory('${id}','${month}',${current+1})">次の10件</button></div>`:''}`);
}
function attendanceCsvText(rows){
 const cell=value=>{let s=String(value??'');if(/^[\s]*[=+\-@]/.test(s)||/^[\t\r\n]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};
 const header=['会員ID','氏名','学年（現在）','所属カテゴリー（現在）','日付','活動名','活動カテゴリー','種別','時間','会場','出欠予定','実際の出欠','出欠の連絡事項'];
 return '\uFEFF'+[header,...rows.map(({r,e,m})=>[r.user_id,m.name,m.grade,m.categories,e?.date||'',e?.title||'日程不明',e?.group_name||'',e?.kind||'',e?.time||'',e?.place||'',r.attendance||'未回答',r.actual,(data.scheduling?.attendance||[]).find(a=>a.user_id===r.user_id&&a.event_id===r.event_id)?.note||''])].map(row=>row.map(cell).join(',')).join('\r\n')+'\r\n';
}
function downloadMemberAttendance(id='',month=''){if(user.role!=='admin')return;
 if(!['coach','admin'].includes(user.role))return;
 const rows=memberAttendanceRows(id,month);if(!rows.length){toast('出力する出欠履歴がありません。');return;}
 if(!id)rows.sort((a,b)=>a.r.user_id.localeCompare(b.r.user_id)||(b.e?.date||'').localeCompare(a.e?.date||''));
 const blob=new Blob([attendanceCsvText(rows)],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='出欠履歴_'+(id||'全会員')+'_'+(month||'全期間')+'.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('出欠履歴CSVを出力しました。');
}


function conflictText(value){const labels={user_id:'会員',event_id:'日程',result_id:'試合ID',id:'ID',title:'題名',name:'氏名',date:'日付',time:'時間',place:'会場',kind:'種類',group_name:'活動区分',note:'連絡事項',actual:'実際の出欠',attendance:'出欠予定',reviewed:'確認済みにする',reviewed_at:'確認日時',updated:'更新日時',body:'内容',status:'状態',grade:'学年',categories:'活動区分',amount:'金額',delete:'削除',member_ids:'参加メンバー',published:'公開',publish:'公開する',map_url:'地図URL',visibility:'公開範囲',entries:'選手記録',points:'得点',rebounds:'リバウンド',assists:'アシスト',fouls:'ファウル',ours:'自チーム得点',theirs:'相手得点',opponent:'対戦相手',video:'動画URL'};const lines=(v,depth=0)=>{if(Array.isArray(v))return v.length?v.map((x,i)=>'【'+(i+1)+'】\n'+lines(x,depth+1)).join('\n'):'（なし）';if(v&&typeof v==='object')return Object.entries(v).map(([k,x])=>{if(k==='user_id')x=data.users?.find(u=>u.id===x)?.name||x;if(k==='event_id')x=data.events?.find(e=>e.id===x)?.title||x;return (labels[k]||k)+'：'+lines(x,depth+1)}).join('\n');if(v===true)return 'はい';if(v===false)return 'いいえ';if(v==null||v==='')return '（なし）';if(typeof v==='string'&&/^[{[]/.test(v)){try{return lines(JSON.parse(v),depth+1)}catch{}}return String(v)};return lines(value);}

const staffAssignmentGroups=['男子A','男子B','女子U９','女子U12','U15アドバンス','U15ベーシック'];
function splitStaffAssignments(value){return String(value||'').split(/[、,，\s]+/).filter(Boolean).map(x=>({'U15A':'U15アドバンス','U15B':'U15ベーシック','女子U9':'女子U９'})[x]||x);}
function staffAssignmentTags(value){const groups=splitStaffAssignments(value).filter(v=>staffAssignmentGroups.includes(v));return groups.length?`<div class="staff-assignment-tags">${groups.map(v=>`<span class="tag">${esc(coachCategoryLabel(v))}</span>`).join('')}</div>`:esc(value&&!['スタッフ','運営'].includes(value)?value:'未設定');}
function toggleStaffAssignment(role){document.querySelector('[data-member-grade]').hidden=role!=='member';document.querySelector('[data-staff-assignment]').hidden=role==='member';document.querySelector('[data-member-only]').hidden=role!=='member';}

function staffDirectoryCsv(people){const cell=value=>{let s=String(value??'');if(/^[\s]*[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};return '\uFEFF'+[['ID','氏名','担当学年・カテゴリー','スタッフ区分','権限','在籍状況'],...people.filter(m=>m.role!=='member').map(m=>[m.id,m.name,m.grade,m.staff_kind||'コーチ',m.role==='admin'?'管理者':'コーチ',m.active?'在籍':'退会・停止'])].map(row=>row.map(cell).join(',')).join('\r\n')+'\r\n';}
function downloadStaffDirectory(){if(user.role!=='admin')return;const blob=new Blob([staffDirectoryCsv(data.users)],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='コーチ・スタッフ一覧_'+new Date().toLocaleDateString('sv-SE')+'.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('コーチ・スタッフ一覧CSVを出力しました。');}

function memberCategoryOptions(current){return current&&!staffAssignmentGroups.includes(current)?[[current,current+'（現在の登録）'],...staffAssignmentGroups]:staffAssignmentGroups;}

function backFromSiteEditor(){if(history.length>1)history.back();else location.hash="dashboard";}

function scrollMemberTable(value){const table=document.getElementById('member-table');if(table)table.scrollLeft=(table.scrollWidth-table.clientWidth)*Number(value)/100;}
function syncMemberScroll(table){const slider=document.querySelector('.member-scroll-controls input');if(slider)slider.value=table.scrollWidth>table.clientWidth?100*table.scrollLeft/(table.scrollWidth-table.clientWidth):0;}

function adminFull(){return user?.role==='admin'&&user.admin_rank===1;}
function adminSection(route){return ({'member-roster':'schedule','messages':'members','skill-videos':'results','admin-settings':'settings','admin-reviews':'attendance-list','staff-approval-settings':'staff-approvals','attendance-rates':'attendance-list','excel':'staff-approvals','billing-individual':'billing-settings','scorecard':'results','score-records':'results','personal-history':'results','team-history':'results'})[route]||route;}
function adminCan(key,write=false){return adminFull()||(user?.role==='admin'&&(write?['edit']:['view','edit']).includes(user.admin_permissions?.[key]));}
function enforcePagePermissions(){if(page==='staff-attendance'&&data.staff_attendance?.available)return;if(user?.role==='coach')document.querySelectorAll('[onclick*="downloadMemberAttendance"],[onclick*="downloadStaffDirectory"]').forEach(el=>el.hidden=true);const section=adminSection(page);if(user?.delegated_coach&&page==='excel')return;const readOnly=user?.role==='admin'?!adminCan(section,true):user?.role==='coach'&&['schedule','attendance-list','results'].includes(section);if(!readOnly||section==='dashboard')return;const root=document.querySelector('.workspace');if(!root)return;root.querySelectorAll('form input,form select,form textarea,form button').forEach(el=>el.disabled=true);const mutators=/staffIntroForMember|staffIntroForm|resultForm|statsImportForm|scoreImportForm|gameStatsForm|userForm\(|removeMember|memberApprovalForm|registrationReviewForm|eventForm|bulkEventForm|scheduleDocumentForm|removeScheduleDocument|activityDetailsForm|eventDetailsForm|matchRosterForm|confirmAttendance|saveActual|submitStaffApproval|setStaffApproval|approveStaffWeek|staffActivityForm|approvalForm|syncExcel|collectionReceiptForm|feeAdjustment|previewBilling|saveSettings/;root.querySelectorAll('[onclick],[onchange]').forEach(el=>{if(mutators.test((el.getAttribute('onclick')||'')+' '+(el.getAttribute('onchange')||''))){if(el.getAttribute('onclick')?.startsWith('userForm')){el.textContent='詳細';}else el.hidden=true;}});if(section==='schedule'||section==='attendance-list')root.querySelectorAll('button').forEach(el=>{if(/編集|公開|登録|削除|確認済みに|未確認に/.test(el.textContent))el.hidden=true;});root.querySelectorAll('[data-billing-profiles] select').forEach(el=>{if(el.getAttribute('onchange')?.includes('filterBillingMember'))el.disabled=false;});}
const dashboardWithPermissions=dashboard;dashboard=function(){const scrolls=new Map([...document.querySelectorAll('[data-attendance-event]')].map(el=>[el.dataset.attendanceEvent,el.querySelector('.table-wrap')?.scrollLeft||0]));dashboardWithPermissions();enforcePagePermissions();document.querySelectorAll('[data-attendance-event]').forEach(el=>{const table=el.querySelector('.table-wrap');if(table)table.scrollLeft=scrolls.get(el.dataset.attendanceEvent)||0;});};
const modalWithPermissions=modal;modal=function(title,body){modalWithPermissions(title,body);if(user?.role==='coach')document.querySelectorAll('#modal [onclick*="downloadMemberAttendance"],#modal [onclick*="downloadStaffDirectory"]').forEach(el=>el.hidden=true);if(user?.role==='admin'&&!adminCan(adminSection(page),true)&&page!=='dashboard'&&!(page==='staff-attendance'&&data.staff_attendance?.available)&&!(user.delegated_coach&&page==='excel'))document.querySelectorAll('#modal form input,#modal form select,#modal form textarea,#modal form button,#modal .member-form-guardians button').forEach(el=>el.disabled=true);};

function eventCategoryField(value){const selected=String(value).split(/[、,]/).map(x=>x.trim()==='年長・小学生'?'小学生':x.trim()).filter(Boolean),options=[...new Set(['男子A','男子B','女子U９','女子U12','U15アドバンス','U15ベーシック','小学生','中学生','合同合宿','イベント',...selected])];return `<div class="field event-category-field"><span>活動区分</span><input type="hidden" name="group_name" value="${esc(selected.join('、'))}"><details class="event-category-picker"><summary><span>${esc(selected.join('、')||'選択してください')}</span></summary><div>${options.map(x=>`<label class="check-row"><input type="checkbox" value="${esc(x)}" ${selected.includes(x)?'checked':''} onchange="updateEventCategories(this)">${esc(x)}</label>`).join('')}</div></details><small class="hint">（複数選択できます）</small></div>`;}
function updateEventCategories(input){const box=input.closest('.event-category-field'),values=[...box.querySelectorAll('input[type="checkbox"]:checked')].map(x=>x.value);box.querySelector('input[name="group_name"]').value=values.join('、');box.querySelector('summary span').textContent=values.join('、')||'選択してください';}


function openPublicMenu(){if(document.getElementById('public-menu-dialog'))return;const dialog=document.createElement('dialog');dialog.id='public-menu-dialog';dialog.setAttribute('aria-labelledby','public-menu-title');dialog.innerHTML=`<div class="public-menu-heading"><div><span>三木　SHINING CHEETAHS</span><h2 id="public-menu-title">メニュー</h2></div><button type="button" aria-label="メニューを閉じる" onclick="this.closest('dialog').close()">×</button></div><nav aria-label="スマホメニュー">${document.querySelector('.header .navlinks').innerHTML}</nav><div class="modal-bottom-actions"><button type="button" class="outline" onclick="this.closest('dialog').close()">閉じる</button></div>`;dialog.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>dialog.close()));dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});const overflow=document.body.style.overflow;dialog.addEventListener('close',()=>{document.body.style.overflow=overflow;dialog.remove();document.querySelector('.public-menu-trigger')?.focus({preventScroll:true});},{once:true});document.body.append(dialog);document.body.style.overflow='hidden';dialog.showModal();}

// Consistent, soft colors for document actions across pages and dialogs.
function styleDocumentActions(){document.querySelectorAll('a.btn,button').forEach(el=>{const label=el.textContent.replace(/\s/g,'');const spreadsheet=/Excel|エクセル|CSV/i.test(label),pdf=/PDF/i.test(label);el.classList.toggle('document-sheet-action',spreadsheet&&!pdf);el.classList.toggle('document-pdf-action',pdf&&!spreadsheet);});}
new MutationObserver(styleDocumentActions).observe(document.body,{childList:true,subtree:true,characterData:true});styleDocumentActions();

function otherActivitiesEditor(){const c=pub.content;const input=(key,label,area=false)=>area?`<label class="field">${label}<textarea name="${key}" rows="4">${esc(c[key]||'')}</textarea></label>`:field(label,key,c[key]||'','text',false);return `<details class="card other-activities-editor"><summary><b>その他の活動を編集</b></summary><p class="hint">トップページの「その他の活動」専用の編集欄です。</p><form onsubmit="saveSettings(event)"><h3>コンディショニングコーチ</h3>${input('conditioning_category','青いカテゴリラベル')}${input('conditioning_title','見出し')}${input('conditioning_intro','開催案内',true)}${input('conditioning_name','コーチ名')}<label class="field">コーチ写真をアップロード<input type="file" accept="image/jpeg,image/png,image/webp" onchange="uploadPhoto(this,'conditioning_photo')"></label>${input('conditioning_photo','写真URL（空欄はNO IMAGE）')}${input('conditioning_comment','自己紹介・サポート内容',true)}${input('conditioning_contact','連絡についての案内',true)}${input('conditioning_instagram','コーチのInstagram URL')}<hr><h3>みきティブ</h3>${input('mikitiv_category','青いカテゴリラベル')}${input('mikitiv_title','見出し')}${input('mikitiv_intro','認定登録の紹介',true)}${input('mikitiv_heading','説明の見出し')}${input('mikitiv_description','説明文',true)}${input('mikitiv_url','みきティブについてのURL')}${input('mikitiv_clubs_url','認定クラブ一覧のURL')}<div class="error" role="alert"></div><div class="registration-actions"><button class="lime">その他の活動を保存</button></div></form></details>`;}

function practiceSlotRow(group,row={}){return `<div class="practice-slot-row" data-group="${esc(group)}"><label class="field">曜日<select data-slot="day">${['月','火','水','木','金','土','日'].map(day=>`<option ${day===(row.day||'土')?'selected':''}>${day}</option>`).join('')}</select></label><label class="field">開始時間<input data-slot="start" type="time" value="${esc(row.start||'')}" required></label><label class="field">終了時間（任意）<input data-slot="end" type="time" value="${esc(row.end||'')}"></label><button type="button" class="outline" onclick="this.closest('.practice-slot-row').remove()">削除</button></div>`;}
function practiceScheduleEditor(c){let slots=[];try{slots=JSON.parse(c.practice_slots||'[]')}catch{}if(!slots.length&&c.practice){for(const part of c.practice.split('／')){const group=part.includes('中学生')?'中学生':'年長・小学生';for(const m of part.matchAll(/([月火水木金土日])曜日?\s*(\d{1,2}:\d{2})[〜～~－-](\d{1,2}:\d{2})?/g))slots.push({group,day:m[1],start:m[2].padStart(5,'0'),end:m[3]?.padStart(5,'0')||''});}}return `<section class="practice-schedule-editor"><h3>通常の練習日</h3><p class="hint">対象ごとに複数の曜日・時間を登録できます。</p>${['年長・小学生','中学生'].map(group=>`<fieldset class="card"><legend>${group}</legend><div class="practice-slot-list">${slots.filter(r=>r.group===group).map(r=>practiceSlotRow(group,r)).join('')}</div><button type="button" class="outline" data-group="${group}" onclick="this.previousElementSibling.insertAdjacentHTML('beforeend',practiceSlotRow(this.dataset.group))">＋ 練習日を追加</button></fieldset>`).join('')}</section>`;}

