function guardianCallButton(m){const parents=data.guardian_contacts?.[m.id]||[];if(parents.length===1&&parents[0].phone)return `<a class="btn outline small guardian-call" href="tel:${esc(parents[0].phone)}" aria-label="${esc(m.name)}さんの${esc(parents[0].name)}へ電話">☎ 保護者へ連絡</a>`;return `<button type="button" class="outline small guardian-call" data-member="${esc(m.id)}" onclick="chooseGuardianContact(this.dataset.member)">☎ 保護者へ連絡</button>`;}
