function openTrialDetails(id){const e=pub.events.find(e=>e.id===id);if(!e)return;modal('体験会の詳細',`<h3>${esc(e.title)}</h3><p>${esc(e.date)} ${esc(e.time)}</p><p>会場：${esc(e.place)}</p><p class="service-text">${esc((e.note||'').replace(/年長[・、]?/g,''))}</p><p>持ち物：${esc(pub.content.equipment||'')}</p><button type="button" class="lime" data-event="${esc(e.id)}" onclick="trialForm(this.dataset.event)">この体験会に参加する</button>`);}

let skillVideoCategory='';
function skillVideosPage(){const edit=adminCan('results',true),rows=(data.skill_videos||[]).filter(v=>!skillVideoCategory||v.group_name===skillVideoCategory),groups=[...new Set((data.skill_videos||[]).map(v=>v.group_name))];return heading('スキルアップ動画','練習や自主トレに役立つ動画を確認できます。',edit?'<button class="lime" onclick="skillVideoForm()">＋ 動画を追加</button>':'')+`<label class="field">対象カテゴリー<select onchange="skillVideoCategory=this.value;dashboard()"><option value="">すべて</option>${groups.map(g=>`<option ${g===skillVideoCategory?'selected':''}>${esc(g)}</option>`).join('')}</select></label><div class="skill-video-grid">${rows.map(v=>`<article class="card skill-video-card"><span class="tag">${esc(v.group_name)}</span><h2>${esc(v.title)}</h2><p class="hint">${esc(v.date)}</p><iframe src="${esc(youtubeEmbed(v.video))}" title="${esc(v.title)}" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe><p class="service-text">${esc(v.note)}</p><div class="toolbar"><a class="text-link" href="${esc(v.video)}" target="_blank" rel="noopener noreferrer">YouTubeで見る</a>${edit?`<button class="outline" data-id="${esc(v.id)}" onclick="skillVideoForm(this.dataset.id)">編集</button>`:''}</div></article>`).join('')||'<div class="card empty">スキルアップ動画はまだ登録されていません。</div>'}</div>`;}
function skillVideoForm(id=''){if(!adminCan('results',true))return;const v=data.skill_videos.find(v=>v.id===id)||{id:'',date:new Date().toLocaleDateString('sv-SE'),group_name:'全員',revision:0};modal(id?'スキルアップ動画を編集':'スキルアップ動画を追加',`<form onsubmit="saveSkillVideo(event,'${esc(id)}',${v.revision})">${field('タイトル','title',v.title||'').replace('<input ','<input maxlength="120" ')}<div class="form-grid">${field('日付','date',v.date,'date')}</div><label class="field">説明・練習のポイント<textarea name="note">${esc(v.note||'')}</textarea></label>${field('YouTube限定公開URL','video',v.video||'','url')}<p class="hint">試合動画と同様、YouTubeのURLを登録します。限定公開動画もURLを知っている人は閲覧できます。</p><div class="error" role="alert"></div><div class="dialog-actions">${id?`<button type="button" class="outline danger" onclick="deleteSkillVideo('${esc(id)}',${v.revision})">動画を削除</button>`:''}<button class="lime">保存する</button></div></form>`);}
async function saveSkillVideo(ev,id,revision){ev.preventDefault();await submit(ev,'skill_video',{...Object.fromEntries(new FormData(ev.target)),group_name:data.skill_videos.find(v=>v.id===id)?.group_name||'全員',id,revision},'動画を保存しました。');}
async function deleteSkillVideo(id,revision){if(!await confirmAction('動画を削除しますか？','スキルアップ動画の掲載を削除します。'))return;try{await api('skill_video',{id,revision,delete:true});$('#modal').close();await refresh();toast('動画を削除しました。');}catch(e){toast(e.message);}}

const portalBeforeReceipts=portalContent;portalContent=function(staff,admin){const body=portalBeforeReceipts(staff,admin),kind=({'payments':'fees','checkout':'fees','billing-settings':'fees','shop':'shop','shop-admin':'shop','surveys':'lunch','survey-admin':'lunch','finance-report':'accounting','finance-admin':'accounting','messages':'refund'})[page];return body+(kind?receiptPanel(kind):'')+(page==='billing-settings'?receiptPanel('refund'):'');};

let coachHomeNavigation=[];
function coachCardHome(){return heading('コーチホーム','確認する項目を選んでください。')+homeAnnouncements()+coachHomeSummary()+`<div class="admin-home-links dashboard-shortcuts">${coachHomeNavigation.filter((x,i,all)=>all.findIndex(y=>y[0]===x[0])===i).map(([id,icon,label])=>`<a class="card" href="#${id}"><h2><span class="admin-shortcut-icon" aria-hidden="true">${icon}</span><span>${esc(label)}</span></h2><span class="text-link">開く →</span></a>`).join('')}</div>`;}
